select 'tables' k, count(*)::text n, '' h from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relkind='r'
union all select 'columns', count(*)::text, md5(string_agg(table_schema||'.'||table_name||'.'||column_name||':'||data_type||':'||is_nullable||':'||coalesce(column_default,''), ',' order by table_schema,table_name,column_name collate "C")) from information_schema.columns where table_schema in ('public','private')
union all select 'policies', count(*)::text, md5(string_agg(schemaname||tablename||policyname||cmd||permissive||array_to_string(roles,',')||coalesce(qual,'')||coalesce(with_check,''), ',' order by schemaname,tablename,policyname collate "C")) from pg_policies where schemaname in ('public','private','storage')
union all select 'triggers', count(*)::text, md5(string_agg(pg_get_triggerdef(t.oid), ',' order by pg_get_triggerdef(t.oid) collate "C")) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and (n.nspname in ('public','private') or c.relname='users' and n.nspname='auth')
union all select 'indexes', count(*)::text, md5(string_agg(indexdef, ',' order by indexdef collate "C")) from pg_indexes where schemaname in ('public','private')
union all select 'functions', count(*)::text, md5(string_agg(pg_get_functiondef(p.oid), ',' order by p.proname collate "C", pg_get_function_identity_arguments(p.oid) collate "C")) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.proname not like 'tmp\_%' and p.proname<>'pgrst_watch' and not exists (select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')
union all select 'constraints', count(*)::text, md5(string_agg(conname||pg_get_constraintdef(c.oid), ',' order by conname||pg_get_constraintdef(c.oid) collate "C")) from pg_constraint c join pg_namespace n on n.oid=c.connamespace where n.nspname in ('public','private')
union all select 'rls', count(*)::text, '' from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relrowsecurity
union all select 'tbl_acl', count(*)::text, md5(string_agg(table_schema||table_name||grantee||privilege_type, ',' order by table_schema||table_name||grantee||privilege_type collate "C")) from information_schema.role_table_grants where table_schema in ('public','private') and grantee in ('anon','authenticated') and privilege_type<>'MAINTAIN'
union all select 'fn_acl', count(*)::text, md5(string_agg(routine_schema||routine_name||grantee, ',' order by routine_schema||routine_name||grantee collate "C")) from information_schema.role_routine_grants where routine_schema in ('public','private') and grantee in ('anon','authenticated','PUBLIC') and routine_name not like 'tmp\_%' and routine_name<>'pgrst_watch'
union all select 'cron', count(*)::text, md5(string_agg(jobname||schedule||command, ',' order by jobname collate "C")) from cron.job
union all select 'realtime', count(*)::text, md5(string_agg(tablename, ',' order by tablename collate "C")) from pg_publication_tables where pubname='supabase_realtime';
